    "title_text": {
      "type": "Text",
      "props": {
        "text": "Kyoto Itinerary for a Couple: October 2026",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This two-day plan for October 18-19, 2026, balances Kyoto's most iconic temples and serene walks with rich culinary experiences. The itinerary is designed for a calm pace, with ample time for photography, and groups sights geographically to minimize travel time and maximize enjoyment."
      },
      "children": []
    },
    "planning_card": {
      "type": "Card",
      "props": {},
      "children": [
        "planning_stack"
      ]
    },
    "planning_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "planning_title",
        "planning_intro",
        "cost_table",
        "transport_tip"
      ]
    },
    "planning_title": {
      "type": "Text",
      "props": {
        "text": "Planning & Budget Context",
        "variant": "h2"
      },
      "children": []
    },
    "planning_intro": {
      "type": "Text",
      "props": {
        "text": "This schedule focuses on Eastern, Western, and Southern Kyoto to create a relaxed and immersive experience. Your budget of JPY 40,000 for two people is well-suited for the activities listed below."
      },
      "children": []
    },
    "cost_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "item",
            "label": "Item"
          },
          {
            "key": "cost",
            "label": "Cost"
          }
        ],
        "rows": [
          {
            "item": "Estimated Total (2 people)",
            "cost": "JPY 32,000 - JPY 36,000"
          },
          {
            "item": "Transport",
            "cost": "~JPY 5,000"
          },
          {
            "item": "Food",
            "cost": "~JPY 24,000"
          },
          {
            "item": "Admissions",
            "cost": "~JPY 3,200"
          }
        ],
        "domain": "generic"
      },
      "children": []
    },
    "transport_tip": {
      "type": "Text",
      "props": {
        "text": "Transport Tip: Consider purchasing a Kyoto City Bus & Subway 1-Day Pass (JPY 1,100 per person) for each day to simplify travel within the city. JR lines for Arashiyama and Fushimi Inari will be separate but are inexpensive."
      },
      "children": []
    },
    "divider_1": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "day1_title": {
      "type": "Text",
      "props": {
        "text": "Day 1: Eastern Kyoto's Charm & Gion's Night (Oct 18)",
        "variant": "h2"
      },
      "children": []
    },
    "day1_morning_card": {
      "type": "Card",
      "props": {},
      "children": [
        "day1_morning_stack"
      ]
    },
    "day1_morning_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "day1_morning_image",
        "day1_morning_content_stack"
      ]
    },
    "day1_morning_image": {
      "type": "Image",
      "props": {
        "url": "../assets/r_000008_01_1_kiyomizu-dera_temple.jpg",
        "fit": "cover",
        "height": 180
      },
      "children": []
    },
    "day1_morning_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
